// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // Fuzz parameters: a block number to roll to (bn) and a caller private key seed (pkSeed)
    // We let the fuzzer pick a block number; vm.roll will set block.number accordingly.
    function testFuzz_property(uint256 bn, uint256 pkSeed) public {
        // keep bn in a reasonable range but wide enough to hit both congruence classes mod 15
        uint256 targetBlock = bound(bn, 1, 10000);
        vm.roll(targetBlock);

        // ensure timestamp strictly increases relative to stored pastBlockTime (initial 0), so any positive time works
        vm.warp(block.timestamp + 1);

        // derive an EOA from pkSeed to act as msg.sender
        address actor = vm.addr(uint256(keccak256(abi.encodePacked(pkSeed))));
        vm.deal(actor, 10 ether);

        // call fallback by making a low-level call from actor sending exactly 10 ether
        bool ok;
        vm.prank(actor);
        // use try/catch via low-level call to observe whether it reverted
        (ok,) = address(c).call{value: 10 ether}("");

        // General rule (one assertion): For the reference contract, after such a successful call (ok==true)
        // the contract's balance is zero iff block.number % 15 == 0.
        // We assert the property reading address(c).balance and block.number.
        // This single assert is satisfied by the reference for all admissible inputs,
        // and the mutant that flips == to != will violate it for some block numbers.
        if (ok) {
            bool refShouldHaveEmptied = (block.number % 15 == 0);
            assertTrue((address(c).balance == 0) == refShouldHaveEmptied);
        } else {
            // If the call reverted, the reference still must preserve its balance (call didn't complete and pastBlockTime not updated)
            // The reference never intentionally reverts inside fallback aside from require checks; ensure that when call reverted,
            // the contract still has its original balance (10 ether) — this is a valid observation of behavior.
            assertTrue(address(c).balance == 10 ether);
        }
    }
}
